def free_space(final_masks, skip, height, width):
    """Pixels that are at least one pixel away from every other mask."""
    used = np.zeros((height, width), dtype=np.uint8)
    for j, m in enumerate(final_masks):
        if j != skip and m is not None and m.any():
            used |= m.astype(np.uint8)
    if used.any():
        used = cv2.dilate(used, np.ones((3, 3), np.uint8))
    return ~used.astype(bool)


def rescue_empty(final_masks, boxes, height, width, min_area=4):
    """Make sure every cell still has a non-empty, non-overlapping mask."""
    for i, m in enumerate(final_masks):
        if m is not None and m.sum() >= min_area:
            continue
        box = boxes[i]
        free = free_space(final_masks, i, height, width)
        rescued = None
        for scale in (1.0, 0.8, 0.6, 0.45, 0.3, 0.15):
            cand = largest_component(
                ellipse_mask(box, height, width, scale=scale) & free)
            if cand.sum() >= min_area:
                rescued = cand
                break
        if rescued is None:
            # carve a tiny disc at the box centre out of the neighbours
            cx = int(np.clip(round((box[0] + box[2]) / 2.0), 1, width - 2))
            cy = int(np.clip(round((box[1] + box[3]) / 2.0), 1, height - 2))
            disc = np.zeros((height, width), dtype=np.uint8)
            cv2.circle(disc, (cx, cy), 2, 1, -1)
            rescued = disc.astype(bool)
            # keep a >=1 pixel gap by clearing a ring around the new disc
            ring = cv2.dilate(disc, np.ones((5, 5), np.uint8)).astype(bool)
            for j, other in enumerate(final_masks):
                if j != i and other is not None and other.any():
                    final_masks[j] = largest_component(other & ~ring)
        final_masks[i] = rescued
    return final_masks

