    return float(xs.mean()), float(ys.mean())


def split_region(region, target, height, width, min_area):
    """Split a donor region in two: the part that belongs to ``target`` and the rest.

    Used when a cell was completely swallowed by a neighbour (e.g. duplicated or
    nested annotations): both cells then get a sizeable share of the region.
    """
    if region.sum() < 2 * min_area:
        return None
    ys, xs = np.nonzero(region)
    inside = target & region
    cx_t, cy_t = centroid(inside) if inside.any() else centroid(target)
    rest = region & ~target
    cx_o, cy_o = centroid(rest) if rest.sum() >= min_area else centroid(region)
    if np.hypot(cx_t - cx_o, cy_t - cy_o) < 1.5:
        # centroids coincide (identical annotations): cut along the longer axis
        if xs.max() - xs.min() >= ys.max() - ys.min():
            keep = xs <= np.median(xs)
        else:
            keep = ys <= np.median(ys)
    else:
        d_t = (xs - cx_t) ** 2 + (ys - cy_t) ** 2
        d_o = (xs - cx_o) ** 2 + (ys - cy_o) ** 2
        keep = d_t < d_o
    part = np.zeros((height, width), dtype=bool)
